   pub(crate) fn follow_fresh_ids(cards: &mut [CardInstance], events: &[GameEvent]) {
       for event in events {
           let (GameEvent::CardPlayed { instance_id, former_id: Some(former), .. }
           | GameEvent::Summoned { instance_id, former_id: Some(former), .. }
           | GameEvent::ControlChanged { instance_id, former_id: Some(former), .. }) = event
